// ============================================================
// Date lookups -- derived from real filesystem mtimes (this repo has
// no git history to date-stamp requirements against), not guessed.
// Migration dates: `stat -c '%y' deployment/migrations/*.sql`.
// Spec dates: `find e2e/tests -iname '*.spec.ts' -printf '%TY-%Tm-%Td'`.
// ============================================================
const MIGRATION_DATE = {}
;[
  [[1, 3], '2026-08-06'],
  [[4, 10], '2026-08-07'],
  [[11, 13], '2026-08-08'],
  [[14, 27], '2026-08-09'],
  [[28, 29], '2026-08-10'],
  [[30, 30], '2026-08-14'],
  [[31, 32], '2026-08-15'],
  [[33, 35], '2026-08-16'],
  [[36, 40], '2026-08-17'],
  [[41, 44], '2026-08-18'],
  [[45, 47], '2026-08-19'],
  [[48, 48], '2026-08-20'],
  [[49, 52], '2026-08-21'],
  [[53, 56], '2026-08-22'],
  [[57, 63], '2026-08-23'],
  [[87, 88], '2026-09-01'],
  [[89, 104], '2026-09-02'],
  [[105, 106], '2026-09-03'],
].forEach(([[lo, hi], date]) => {
  for (let n = lo; n <= hi; n++) MIGRATION_DATE[n] = date
})

// Requirements built with no new migration (app-layer only / read of
// an existing view) -- dated to when they actually shipped this
// session rather than left blank.
const NO_MIGRATION_DATE = '2026-08-23'

function dateForMigrations(migStr, fallback = NO_MIGRATION_DATE) {
  const nums = String(migStr).match(/\d{3}/g)
  if (!nums || nums.length === 0) return fallback
  const latest = Math.max(...nums.map((n) => parseInt(n, 10)))
  return MIGRATION_DATE[latest] || fallback
}

