function datesForSpecs(specStr) {
  const names = String(specStr).match(/[\w-]+\.spec\.ts/g)
  if (!names || names.length === 0) return ''
  const dates = [...new Set(names.map((n) => SPEC_DATE[n]).filter(Boolean))].sort()
  return dates.join(' / ')
}

