// ============================================================
// Security Findings — pre-launch audit, 2026-08-24. Four parallel
// domain audits (RLS/database, auth/session/admin, payment/escrow,
// XSS/injection/secrets/uploads) plus a direct `npm audit` run across
// all 6 apps. Tracked here from discovery through fix/closure, per
// user request -- each row's Status/Date Fixed/Verification columns
// are updated in place as remediation lands, not re-logged as new rows.
// ============================================================
const securityFindingsRaw = [
  ['ID', 'Module', 'Severity', 'Finding', 'Location', 'Exploit Scenario', 'Status', 'Date Found', 'Date Fixed', 'Fix + Verification'],
  ['SEC-001', 'Auth & Admin', 'CRITICAL', 'Signup accepts a client-controlled role, including admin', 'apps/*/src/app/auth/signup/route.ts (all 6 apps); deployment/migrations/010,022,030,038,047 (handle_email_confirmed reads raw_user_meta_data.role with no allowlist)', 'Sign up with role=admin in the request; confirm the emailed OTP; you are a platform admin on every app.', 'Fixed', '2026-08-24', '2026-08-24', 'handle_email_confirmed() (067, corrected in 069 after a regression: the rewrite dropped a required pillar_memberships.role column, breaking every non-default-role signup — restored from 047\'s original body with only the admin-rejection added) now forces any \'admin\' role attempt back to \'candidate\'. apps/greyin-b2b/src/app/auth/signup/route.ts also allowlists role app-side (the other 5 apps already only passed safe, ternary-limited values). Verified via direct SQL simulating real signup trigger fires (candidate/employer/stackedge-builder/admin-attempt), and by the full regression suite (admin-llm.spec.ts, governance-voting.spec.ts, gate-settings-update.spec.ts, discussions.spec.ts, karma-and-anonymous.spec.ts, verification.spec.ts) plus e2e/tests/cross-platform/security-regressions.spec.ts (new permanent regression guard).'],
  ['SEC-002', 'Auth & Admin', 'CRITICAL', 'profiles.role has no column-level protection from a direct PATCH', 'deployment/migrations/001_initial_schema.sql:52-54 ("Users can update own profile" UPDATE policy, row-scoped only)', 'Any logged-in user: PATCH /rest/v1/profiles?id=eq.<self> {"role":"admin"} with the public anon key.', 'Fixed', '2026-08-24', '2026-08-24', 'enforce_profile_role_immutable() BEFORE UPDATE trigger (067, corrected in 070 after a regression: the trusted-caller exemption only checked auth.role()=\'service_role\', a JWT claim that isn\'t set when a SECURITY DEFINER function like handle_email_confirmed calls it internally — now also checks current_user IN (\'service_role\',\'postgres\',\'supabase_admin\')). Blocks any role change by a non-admin session; service_role/postgres-owned internal paths still work. Verified via direct SQL (self-escalation attempt blocked, legitimate service_role promotion still works) and e2e/tests/cross-platform/security-regressions.spec.ts (real GoTrue password-grant token, direct PostgREST PATCH attempt, DB-state assertion).'],
  ['SEC-003', 'Payments & Escrow', 'CRITICAL', 'Gig order amount is fully client-supplied at creation', 'apps/freeagent-marketplace/src/app/api/orders/create/route.ts:16,36,84', 'POST a crafted amount far below the gig\'s real price.price_min; buy any gig for ₹1.', 'Fixed', '2026-08-24', '2026-08-24', 'orders/create/route.ts no longer reads amount from the request at all — recomputed server-side as gig.price_min × package multiplier (basic=1/standard=2/premium=3), matching checkout/[id]/page.tsx\'s own display formula. Verified by e2e/tests/cross-platform/security-regressions.spec.ts: a crafted amount:1 request against a ₹2000 gig still creates a ₹2000 order.'],
  ['SEC-004', 'Payments & Escrow', 'CRITICAL', 'Payment verification is not bound to the specific order being marked paid', 'apps/freeagent-marketplace/src/app/api/orders/verify/route.ts:20,38-39', 'Complete one real cheap payment, then replay that verified (order_id, payment_id, signature) triple against a different, expensive order — it is marked paid with zero payment.', 'Fixed', '2026-08-24', '2026-08-24', 'verify/route.ts now fetches the order\'s own stored razorpay_order_id first and rejects if it doesn\'t match the request\'s razorpayOrderId, before ever trusting the signature. Defense in depth at the DB layer too: gig_orders_enforce_transition (068, extended in 073) locks payment_status permanently once \'captured\', so even a same-order first-capture race can\'t be replayed twice. Verified via direct SQL (capture-once, replay-with-different-payment-id-same-status-value blocked) and the full freeagent regression suite (checkout-payment.spec.ts, webhook-payment-captured.spec.ts, order-lifecycle.spec.ts, escrow-workflow.spec.ts).'],
  ['SEC-005', 'Payments & Escrow', 'CRITICAL', 'Escrow release and payout never check payment_status=\'captured\'', 'apps/freeagent-marketplace/src/app/api/orders/update-status/route.ts:48-56; .../api/payouts/request/route.ts:26-30; earnings/page.tsx:32-34', 'Two accounts walk a never-paid order to \'completed\' and request a real payout of an amount that was never actually charged.', 'Fixed', '2026-08-24', '2026-08-24', 'gig_orders_enforce_transition trigger (067/068) requires OLD.payment_status=\'captured\' before allowing in_progress/delivered/completed transitions — DB-enforced regardless of what the API routes themselves check. 073 extended it to correctly support the real buyer-cancel-refund and admin-dispute-resolution flows after discovering the first version blocked those legitimate paths too (both need to move payment_status after capture, which the original design didn\'t account for). Verified via direct SQL across 7 scenarios (capture, replay-block, amount-tamper-block, buyer-refund, admin-escrow-release, admin-refund, seller-cannot-fake-refund, buyer-cannot-cancel-post-delivery) and the full escrow-workflow.spec.ts/order-lifecycle.spec.ts/earnings-and-payouts.spec.ts suite.'],
  ['SEC-006', 'Data Access (RLS)', 'CRITICAL', 'Unauthenticated, PUBLIC-EXECUTE SECURITY DEFINER Razorpay RPCs', 'deployment/migrations/002_razorpay_integration.sql:141,159-180,183-202 (create_razorpay_order, capture_razorpay_payment, process_razorpay_refund)', 'Call /rpc/capture_razorpay_payment directly with an arbitrary order id — no auth.uid() check, no REVOKE, callable by anyone.', 'Fixed', '2026-08-24', '2026-08-24', 'REVOKE EXECUTE FROM PUBLIC, anon, authenticated on all three (067) — confirmed unused by any real app code (payment status changes go through direct table updates in the webhook/verify routes instead), so this is a pure attack-surface closure with zero functional impact. Verified via direct SQL (authenticated session RPC call blocked with insufficient_privilege).'],
  ['SEC-007', 'Data Access (RLS)', 'CRITICAL', 'award_reputation() lets any caller mint arbitrary Salt & Pepper reputation', 'deployment/migrations/025_reputation.sql:38-44', 'Call the RPC directly for the project_upvoted event type that 064\'s Greyin Score gate specifically trusts; self-mint is_verified_expert.', 'Fixed', '2026-08-24', '2026-08-24', 'REVOKE EXECUTE FROM PUBLIC, anon, authenticated (067) — corrected in 074 after a real regression: 3 of the 4 internal trigger functions that legitimately call it (reputation_on_discussion_created/reply_created/project_created) were never SECURITY DEFINER themselves, so the REVOKE also silently broke discussion/reply/project creation platform-wide (Salt & Pepper AND StackWorks) with "permission denied for function award_reputation". Fixed by making those three SECURITY DEFINER (matching the fourth, project_upvoted, which already was) — the function owner retains implicit execute regardless of the REVOKE, while a direct authenticated RPC call stays blocked. Verified via direct SQL (real project insert + reputation trigger succeeds; direct RPC call from an authenticated session still blocked) and e2e (verification.spec.ts, discussions.spec.ts, karma-and-anonymous.spec.ts all passing).'],
  ['SEC-008', 'Data Access (RLS)', 'CRITICAL', 'verified_outcomes allows self-verification', 'deployment/migrations/031_verification_engine.sql:102-104 (INSERT policy checks only auth.uid() = subject_user_id, nothing pins status)', 'Insert your own {status:\'verified\', score:100} row and become a Verified Expert with a fabricated track record.', 'Fixed', '2026-08-24', '2026-08-24', 'INSERT policy (067) now requires status=\'pending\' on self-submission — \'verified\' is only reachable via the existing counterparty-review UPDATE policy or finalize_expired_verified_outcomes(). Verified via direct SQL (self-submit with status=\'verified\' blocked; self-submit with status=\'pending\' still allowed) and verification.spec.ts.'],
  ['SEC-009', 'Storage & Secrets', 'CRITICAL', 'Candidate resumes stored in a fully public, listable bucket', 'deployment/migrations/019_public_images_bucket.sql:11,16; apps/greyin-b2b/src/components/ResumeSkillsUploader.tsx:52', 'Anonymously list and download every candidate\'s resume (PII) with no authentication at all.', 'Fixed', '2026-08-24', '2026-08-24', 'New private `resumes` bucket (071): public=false, owner+eligible-employer-only RLS (same real-application eligibility shape as company_reviews/professional_references), 5MB limit, application/pdf only. FileUploader.tsx/ResumeSkillsUploader.tsx upload path-scoped under the user\'s own id, using a 30-day signed URL instead of a public URL (chosen over a path-based re-signing refactor since resume_url is also a freely user-editable field elsewhere in the app — apps/greyin-b2b/src/app/jobs/[id]/apply/page.tsx — documented, pragmatic scope decision). Verified via resume-parsing.spec.ts passing end to end against the new private bucket.'],
  ['SEC-010', 'Storage & Secrets', 'CRITICAL', 'Storage bucket has no path scoping, MIME allowlist, or size limit', 'deployment/migrations/019_public_images_bucket.sql:20 (INSERT policy is just auth.role()=\'authenticated\')', 'Any logged-in user uploads an .html file served publicly as HTML from the Supabase origin (phishing/stored-content risk), or uploads unbounded volume to exhaust storage.', 'Fixed', '2026-08-24', '2026-08-24', 'public-images bucket (071) now has a 5MB limit and an image-only MIME allowlist, plus a path-scoped INSERT policy requiring the uploader\'s own user id as the first path segment. All 4 consuming uploader components (apps/greyin-b2b/FileUploader.tsx, apps/stackedge/greymatters-blog/freeagent-marketplace ImageUploader.tsx) updated to actually upload under that path (previously none of them did, which would have broken every image upload the moment the policy went live — caught before deploy, not after). Verified by typecheck across all 4 touched apps plus resume-parsing.spec.ts and the broader freeagent/stackedge/greymatters regression coverage.'],
  ['SEC-011', 'Storage & Secrets', 'CRITICAL', 'A real, signed service_role JWT is committed in the source tree', 'deployment/config/kong.yml:134 (expires 2036, comment admits "valid everywhere")', 'Anyone with repo or build-artifact access gets full RLS bypass on the entire database.', 'Fixed', '2026-08-24', '2026-08-26', 'Rotated at the user\'s explicit direction and timing (previously deliberately deferred pending exactly that decision). New JWT_SECRET generated (openssl rand); new anon and service_role JWTs freshly signed matching the exact existing payload shape (iss:supabase, ref:greyin, role, iat, exp=iat+10yrs) and independently verified via HMAC recomputation before ever being applied. deployment/.env, e2e/.env, and deployment/config/kong.yml all updated; original values backed up locally first. Found and fixed a real gotcha along the way: kong.yml is mounted into the Kong container via a plain bind mount, not a Swarm config object, so editing the file alone did not make Kong pick up the new consumer credentials -- Swarm did not detect a service-spec change, and Kong itself only reads its declarative config at startup, so an explicit `docker service update --force supabase_kong` was required to actually reload it. Confirmed via direct curl that the previously-committed (now rotated-away) key is cryptographically dead (401) while the new anon/service_role keys work end-to-end through Kong -> PostgREST (200). Full stack redeployed: supabase core stack (db/auth/rest/storage/studio/kong/analytics) via a rolling `docker stack deploy` (not the deploy script\'s destructive `stack rm`), frontend stack redeployed for the runtime SERVICE_ROLE_KEY env var, and all 6 apps rebuilt with the new NEXT_PUBLIC_SUPABASE_ANON_KEY build-time inlining. Verified with the full auth e2e suite post-rotation (sso, logout-flow all 6 apps, session-refresh-middleware, password-reset, security-regressions) -- 14/14 passing, proving real signup/login/SSO/logout/session-refresh/password-reset all work end-to-end on the rotated keys, not just curl-level key checks.'],
  ['SEC-012', 'XSS & Injection', 'CRITICAL', 'Stored XSS via unescaped JSON.stringify in a dangerouslySetInnerHTML JSON-LD block', 'apps/greyin-b2b/src/app/jobs/[id]/page.tsx:91 (employer-controlled job description/company fields)', 'An employer\'s job description containing a crafted </script><script> payload executes for every visitor to that job page.', 'Fixed', '2026-08-24', '2026-08-24', 'JSON.stringify output now has < replaced with \\u003c before injection (the standard mitigation for this exact class of JSON-LD/script-tag XSS — valid inside a JSON string, never interpreted as a tag boundary by the HTML parser). Verified via typecheck and deploy; no dedicated e2e assertion added (would require injecting a real XSS payload against prod, judged unnecessary given the fix is a well-established, narrow one-line mitigation).'],
  ['SEC-013', 'Data Access (RLS)', 'CRITICAL', 'collaborators view bypasses the RLS its own migration comment claims it relies on', 'deployment/migrations/059_collaborators.sql (no security_invoker=true; runs as view owner)', 'Any authenticated user reads every StackWorks collaboration and completed FlexPro order pairing on the platform, not just their own.', 'Fixed', '2026-08-24', '2026-08-24', 'ALTER VIEW public.collaborators SET (security_invoker = true) (067, PG15+ feature, confirmed supported on this instance\'s PG 15.1). The view now correctly runs as the querying role, so the underlying project_applications/gig_orders RLS actually applies as the original 059 comment claimed. Verified via direct SQL (an unrelated authenticated user sees 0 rows for pairs they\'re not part of) and worked-together-surfacing.spec.ts / reference-checks.spec.ts (both depend on this view, both still passing).'],
  ['SEC-014', 'Dependencies', 'HIGH', 'Next.js 14.2.4 has a critical CVE bundle (incl. CVSS 9.1 middleware auth bypass) fixed in 14.2.35', 'apps/*/package.json (all 6 apps)', 'CVE-2025-29927 (GHSA-f82v-jwr5-mffw) and a long tail of other high/moderate CVEs; practical impact of the middleware CVE specifically is lower here since real auth checks live in Server Component redirects, not middleware.ts.', 'Fixed', '2026-08-24', '2026-08-24', 'Bumped 14.2.4 -> 14.2.35 across all 6 apps\' package.json (same minor line, non-breaking). npm audit post-bump confirms the CRITICAL finding is gone (down to a handful of remaining "high" findings that need an out-of-scope 15.x major bump). Found and fixed one real regression along the way: apps/freeagent-marketplace/src/app/api/orders/upload-deliverable/route.ts (the only route in the entire codebase that processes a real multipart file upload via formData() and then redirects) started 404ing on the client after its redirect under 14.2.35 — fixed by pinning an explicit 303 status on all 8 NextResponse.redirect() calls in that file (confirmed via a full codebase search that no other route shares this exact upload+redirect shape). Verified via a 21-spec regression sweep across all 6 apps (payments, admin, discussions, reputation, SSO, logout, session-refresh) all passing, plus the specific order-lifecycle.spec.ts re-run clean in isolation after the fix.'],
  ['SEC-015', 'Auth & Admin', 'HIGH', 'Password-reset OTP is brute-forceable', 'apps/*/src/app/auth/reset-password-confirm/route.ts (all 6 apps); no GOTRUE_MAILER_OTP_EXP override (defaults 24h)', 'Request a reset for a victim\'s email, then brute-force the 6-digit code over the 24-hour window — no attempt counting or lockout.', 'Fixed', '2026-08-24', '2026-08-24', 'New shared rate_limit_attempts table + check_rate_limit()/record_rate_limit_attempt() SECURITY DEFINER RPCs (075) -- no direct grants on the table itself, only the RPCs can read/write it, so a client can\'t insert fake "success" rows to erase their own lockout. Wired into reset-password-confirm/route.ts across all 5 apps that have this flow (greyin-b2b, freeagent-marketplace, saltnpepper-community, stackedge, greymatters-blog -- greyin-hub has no signup/password-reset flow at all, SSO-only): 5 failed attempts locks further attempts for 20 minutes, even the genuinely correct code. Verified via direct SQL (independent per-key and per-action tracking, RLS confirmed blocking direct table access for anon while the RPCs work) and a new e2e/tests/greyin-b2b/password-reset.spec.ts lockout test (5 wrong codes, 6th attempt with the real code still rejected) plus the pre-existing legitimate-reset-flow test passing in all 5 apps, deployed and confirmed with zero regressions this round.'],
  ['SEC-016', 'Auth & Admin', 'HIGH', 'Session cookies are not httpOnly/secure, and scoped to the whole .greyin.net apex', 'apps/*/src/middleware.ts, lib/supabase/server.ts (all 6 apps) — @supabase/ssr 0.1.0 defaults, no override', 'A single XSS anywhere on any current or future *.greyin.net subdomain steals a token granting SSO to all 6 apps.', 'Fixed', '2026-08-24', '2026-08-25', 'secure:true, sameSite:\'lax\' added to the session cookie set/remove callbacks in all 6 apps\' middleware.ts (createServerClient, not the crash-prone createBrowserClient in lib/supabase/client.ts -- confirmed safe by re-reading that file\'s own comments before touching anything). httpOnly deliberately NOT added: every app\'s SiteHeader.tsx calls createClient().auth.getUser() client-side to decide Sign-In-vs-logged-in display; an httpOnly cookie is invisible to that call and would break every header platform-wide. Closing that exposure for real needs a genuine refactor (server-rendered auth-state props across all 6 apps), tracked here as a known, deliberate gap rather than forced through. Cookie domain stays apex-scoped (.greyin.net) since that\'s the real SSO mechanism, not an oversight. Staged rollout: greyin-b2b deployed and verified alone first (sso/logout-flow/session-refresh-middleware specs, 9/9 passed) before the remaining 5 apps. Found and fixed a real deploy mistake along the way, unrelated to the cookie change itself: saltnpepper-community\'s redeploy used a build-arg reading a nonexistent env var (SALTNPEPPER_DOMAIN instead of the real COMMUNITY_DOMAIN in deployment/.env), baking an empty NEXT_PUBLIC_SITE_URL into that build and breaking absoluteUrl() across its login/logout/signup routes (TypeError: Invalid URL, caught by a genuine test failure, confirmed via docker service logs, not assumed). Rebuilt with the correct var, redeployed, confirmed clean logs and a working /login route, then re-ran the full 9-test suite clean against the fully-corrected 6-app state.'],
  ['SEC-017', 'Auth & Admin', 'HIGH', 'No signup abuse protection anywhere (no captcha, no rate limit beyond GoTrue defaults)', 'All 6 apps\' signup flows; deployment/supabase-stack.yml has no GOTRUE_SECURITY_CAPTCHA_*', 'Mass automated account creation, directly amplifying SEC-001\'s admin-escalation risk.', 'Partially fixed — rate limit shipped; captcha deliberately deferred pending a user decision', '2026-08-24', '2026-08-25', 'DB-backed rate limit added to all 5 apps with a signup flow (greyin-b2b, greymatters-blog, freeagent-marketplace, saltnpepper-community, stackedge -- greyin-hub has no signup flow, correctly excluded), reusing 075\'s check_rate_limit/record_rate_limit_attempt RPCs with action=\'signup\'. Deliberately keyed by client IP (first entry of X-Forwarded-For, set by the Traefik edge) rather than email -- a mass-signup attacker uses a fresh email every time, so an email-keyed limit would never trigger, unlike SEC-015\'s password-reset case where the key genuinely is the target email. Every attempt is recorded with success=false regardless of GoTrue\'s actual outcome, repurposing the table\'s "failures" counter as a generic "attempts" counter for this action -- a successful account creation is exactly the abuse being limited here, so it has to count toward the cap too (documented inline given it reads unusual next to SEC-015\'s literal-failure semantics on the same table). Threshold: 10 signups/hour/IP. Verified via direct SQL (10th attempt from one IP locks out, unrelated IPs unaffected) and a live end-to-end run against prod (11 real POSTs to greyin-b2b\'s /auth/signup from a spoofed shared X-Forwarded-For: attempts 1-10 processed normally, 11th+ redirected with the lockout message). CORRECTION (2026-08-26): the original verification\'s "no orphaned accounts" claim was wrong -- the admin-API `filter=email.eq.X` check used to confirm that didn\'t actually filter, and 10 real unconfirmed @example.com accounts were left in prod; found and deleted via the admin API once the real GoTrue user list was checked directly. Separately, and more seriously: a few hours after shipping, the fully-rolled-out state was found to have a real availability bug -- every request through this deployment\'s Traefik resolved to the SAME X-Forwarded-For value, \'172.18.0.1\' (Traefik\'s own docker-bridge gateway address, not a real per-client IP; confirmed via `SELECT key, count(*) FROM rate_limit_attempts WHERE action=\'signup\' GROUP BY key`, one shared key already at 20 hits), discovered when it silently blocked the e2e suite\'s own signups. Left as shipped, this would have bucketed every real signup on the platform under one shared key -- locking out signup for EVERYONE after 10 total/hour, not 10 per attacker, a functional regression worse than the abuse it was meant to stop. Immediately cleared the bad rows and fixed the root cause in all 5 apps: the rate limit check/record is now skipped entirely whenever the resolved X-Forwarded-For value is private/link-local/absent (10.x, 172.16-31.x, 192.168.x, 127.x, 169.254.x, ::1, fc/fd IPv6 prefixes) rather than enforced against a meaningless shared key. Re-verified clean: rate_limit_attempts empty for signup after redeploy, and e2e/tests/cross-platform/security-regressions.spec.ts passing again (all signups un-blocked). NOT implemented: GOTRUE_SECURITY_CAPTCHA_* (hCaptcha/Turnstile/etc) -- genuinely closing the "no captcha" half of this finding requires picking and configuring a third-party provider and secret, an external-dependency decision this audit is not making unilaterally per standing guidance; tracked here as a separate, still-open sub-item pending that decision.'],
  ['SEC-018', 'Payments & Escrow', 'MEDIUM', 'No Razorpay webhook idempotency / replay protection', 'apps/freeagent-marketplace/src/app/api/webhooks/razorpay/route.ts:70-76,105-108', 'A replayed payment.captured event on an already-cancelled/refunded order flips it back to paid, enabling a second real refund.', 'Fixed', '2026-08-24', '2026-08-25', 'This route runs as service_role, which enforce_gig_order_transition (073) explicitly trusts and skips -- so nothing in the DB stopped a late/out-of-order webhook event from regressing an order\'s state, only app-layer guards can. Two changes: (1) idempotency -- razorpay_webhooks.event_id already had a real UNIQUE constraint, but a genuine redelivery previously fell through to the outer catch and returned 500 (causing Razorpay to retry the same event forever); now a 23505 unique-violation on insert returns 200 "already processed" immediately, a real no-op instead of a retry storm. Also fixed a latent bug in the same code path: the "mark as processed" update recomputed the fallback event_id with a fresh Date.now() instead of reusing the one actually inserted, silently updating zero rows whenever event.event_id was missing. (2) state guards -- handlePaymentCaptured/handleOrderPaid now only move an order to \'paid\' from \'pending\'/\'authorized\'; handleRefundCreated skips (no update, no duplicate email) if the order is already \'refunded\'. Verified via escrow-workflow.spec.ts and order-lifecycle.spec.ts passing clean after deploy (no regression to the real payment/refund/dispute flows).'],
  ['SEC-019', 'Payments & Escrow', 'MEDIUM', 'Non-timing-safe webhook/verify signature comparisons', 'apps/freeagent-marketplace/src/app/api/webhooks/razorpay/route.ts:21; api/orders/verify/route.ts:23; apps/greyin-b2b/src/app/api/webhooks/razorpay-subscriptions/route.ts:10', 'Plain === on hex digests is theoretically timing-attackable; signature verification itself is genuinely present at all 3 sites.', 'Fixed', '2026-08-24', '2026-08-25', 'Switched from === / !== to crypto.timingSafeEqual (with an explicit length check first, since timingSafeEqual throws rather than returning false on mismatched buffer lengths) at all 3 sites. No functional behavior change -- same accept/reject outcomes, just constant-time -- verified via the same escrow-workflow.spec.ts/order-lifecycle.spec.ts passing clean (both exercise real signature verification end to end).'],
  ['SEC-020', 'Data Access (RLS)', 'MEDIUM', 'company_reviews leaks reviewer_id, de-anonymizing "anonymous" reviews', 'deployment/migrations/058_company_reviews.sql:30-32 (SELECT USING (true) exposes the column; anonymity is UI-only)', '?select=reviewer_id,rating on the company_reviews endpoint de-anonymizes every review.', 'Fixed', '2026-08-24', '2026-08-24', 'Column-level REVOKE SELECT + narrow re-GRANT on (id, company_id, rating, review_text, created_at) only (067) — reviewer_id is now genuinely unreadable via any PostgREST query, not just absent from the app\'s own UI. Corrected in 072 after a regression: apps/greyin-b2b/src/app/companies/[id]/page.tsx legitimately needed to check "have I already reviewed this company" via a WHERE reviewer_id=auth.uid() filter, which the column revoke also blocked (column-level grants restrict any use of the column, including inside a WHERE clause, not just the SELECT list). Fixed with a narrow has_reviewed_company(company_id) SECURITY DEFINER RPC that checks only the caller\'s own membership, never exposing the column via a general grant. Verified via direct SQL (unrelated user\'s reviewer_id SELECT blocked; the new RPC works) and company-reviews.spec.ts passing end to end.'],
  ['SEC-021', 'Auth & Admin', 'MEDIUM', 'Open-redirect filter bypass via backslash in ?next= handling', 'apps/*/src/app/auth/login/route.ts (all 6 apps); lib/site-url.ts absoluteUrl()', '?next=/\\evil.com passes the startsWith("/") check; browsers normalize \\ to //, redirecting off-platform after login (phishing).', 'Fixed', '2026-08-24', '2026-08-25', 'Two real instances of the same bug found and fixed, not just one. (1) auth/login/route.ts\'s POST handler: startsWith(\'/\') && !startsWith(\'//\') missed the backslash case -- confirmed via node\'s URL constructor that /\\evil.com resolves to https://evil.com/ (browsers normalize \\ to / while parsing). Fixed by also rejecting any backslash in `next`. (2) login/page.tsx, found while the first round of fixes was already deploying: every app\'s `if (user) { redirect(next || \'/dashboard\') }` for an already-logged-in visitor had NO validation at all -- worse than the route.ts case, since visiting /login?next=https://evil.com while logged in redirects immediately, no form submission needed. Required a second, clean rebuild of all 6 apps to guarantee both fixes actually shipped together (the page.tsx edit landed mid-deploy of the route.ts-only first round). Both fixed identically across all 6 apps with the same relative/no-double-slash/no-backslash check. Verified via a new permanent e2e test in security-regressions.spec.ts covering both cases directly against prod, using page.request with maxRedirects:0 to inspect the server\'s raw Location header rather than actually navigating to a third-party domain -- passing clean.'],
  ['SEC-022', 'XSS & Injection', 'MEDIUM', 'Unescaped user input interpolated into PostgREST .or() filter strings', 'apps/greymatters-blog/src/app/search/page.tsx:25; apps/greyin-b2b/src/app/jobs/page.tsx:50; apps/freeagent-marketplace/src/app/gigs/page.tsx:60 and similar search pages', 'A comma or close-paren in a search query injects extra filter clauses; RLS caps the blast radius but the input is unsanitized in a query DSL.', 'Fixed', '2026-08-24', '2026-08-26', '13 sites across 7 files (search/page.tsx in all 5 apps that have one -- 2-3 .or() calls each -- plus greyin-b2b/jobs/page.tsx and freeagent-marketplace/gigs/page.tsx) had raw, unescaped user input interpolated into PostgREST .or() filter strings. Fixed with a small inline sanitizer (`s.replace(/[,()".{}\\\\]/g, \' \').trim()`) applied to the search term before every interpolation, stripping the characters that carry syntactic meaning in PostgREST\'s filter DSL (comma separates OR-conditions, parens group them, braces delimit the cs.{...} array-contains operator\'s literal value used by the people-search branch) rather than trying to selectively quote/escape them. Empirically confirmed the injection was real before fixing (a direct PostgREST call with an injected `,id.eq.<uuid>` condition measurably changed the result set) and confirmed clean after deploy (the same crafted query now renders as literal text -- "No results for x,id.eq.00000000-..." -- on the live search page, and normal single-word/multi-word searches are unaffected).'],
  ['SEC-023', 'Data Access (RLS)', 'MEDIUM', 'mentor_session_slots lets a mentor resell a paid seat and exposes recording_url pre-purchase', 'deployment/migrations/062_mentor_monetization.sql:344-347 (WITH CHECK only auth.uid()=mentor_id, unlike 056:63); 056:44-50', 'A mentor flips their own booked slot back to open and nulls gig_order_id, reselling an already-paid seat; recording_url is visible on any open-status slot.', 'Fixed', '2026-08-24', '2026-08-26', 'Two real gaps, migration 076. (1) Postgres combines multiple permissive UPDATE policies on the same table with OR at both USING and WITH CHECK -- 062\'s "attach a recording" policy\'s WITH CHECK only required auth.uid()=mentor_id, so it (not 056\'s stricter, status=\'open\'-only policy) governed any direct update to a \'booked\' row, letting a mentor PATCH status back to \'open\' and null gig_order_id, reselling an already-paid seat. Fixed with a BEFORE UPDATE trigger (same pattern as enforce_gig_order_transition/073) blocking any direct change to mentor_id/gig_id/gig_order_id, and blocking any status change away from \'booked\' outside the trusted book_mentor_slot()/service_role path. (2) recording_url was readable via the SELECT policy on any \'open\' slot regardless of purchase -- confirmed the app\'s own UI already rendered it safely (Server Component, URL never serialized to the client for non-owners) but a direct PostgREST call bypassing the UI got the real URL. Fixed via column-level REVOKE SELECT(recording_url) plus a new get_visible_recording_urls(slot_ids) SECURITY DEFINER RPC (mentor, original buyer, or genuine purchaser only); recording_price stays public since both app pages need it to render "Buy access". Updated both freeagent-marketplace pages that read recording_url (mentor-sessions/[gigId] and mentor-sessions/manage) to use the RPC instead of the raw column, using recording_price as the "has a recording" signal for the pages\' own filtering (column REVOKE blocks a column\'s use in a WHERE/filter, not just SELECT, so filtering by recording_url itself was no longer possible either). Verified via direct SQL in a rolled-back transaction: the resell exploit is blocked with the exact error, legitimate mentor recording-attach and own-open-slot-cancel still succeed, anon gets 0 rows reading the column directly, and the RPC correctly returns the URL for the real buyer but nothing for an unrelated stranger. tsc clean, deployed, smoke-checked.'],
  ['SEC-024', 'Data Access (RLS)', 'MEDIUM', 'create_job_referral_notification() has no real authorization beyond being logged in', 'deployment/migrations/040_job_referral_notification.sql:23-38', 'Attacker-controlled title/body pushed into any user\'s notification inbox.', 'Fixed', '2026-08-24', '2026-08-26', 'The real caller (apps/greyin-b2b/src/app/api/jobs/[id]/refer/route.ts) already derived job_title/referrer_name server-side, but the SECURITY DEFINER RPC itself was GRANTed to authenticated with no further checks -- a direct call bypassing that route could pass any p_job_title/p_referrer_name/p_job_id it wanted, including a nonexistent job. Migration 077 drops both text parameters entirely and derives them itself: referrer_name from the caller\'s own profiles row (auth.uid()), job_title from a real jobs row (RAISE EXCEPTION if p_job_id doesn\'t exist -- also closes the unvalidated-job-id gap). Old 4-arg signature REVOKEd and dropped so a stale/direct call can\'t hit the vulnerable version. Verified via direct SQL in a rolled-back transaction: a nonexistent job_id is rejected, and a legitimate call produces a notification whose title/body genuinely come from the real profile/job rows, not client input. App route updated to the new 2-arg call, tsc clean, deployed, smoke-checked.'],
  ['SEC-025', 'Data Access (RLS)', 'MEDIUM', 'subscription_plans has no RLS enabled at all', 'deployment/migrations/039_subscriptions.sql:38 — the only CREATE TABLE public.* across 66 migrations missing ENABLE ROW LEVEL SECURITY', 'Verify Supabase default grants don\'t let anon/authenticated write to pricing; currently unprotected by any policy.', 'Fixed', '2026-08-24', '2026-08-26', 'Turned out to be worse than the original MEDIUM rating: checked information_schema.role_table_grants directly and found anon/authenticated hold real INSERT/UPDATE/DELETE/TRUNCATE grants on this table (this instance\'s schema-wide default grants, not the SELECT-only the migration\'s own explicit GRANT line implied) -- with RLS disabled, those grants were the only gate, meaning any unauthenticated visitor could directly PATCH/DELETE the platform\'s real pricing rows via PostgREST. Confirmed via query that subscription_plans was the ONLY public table with RLS disabled platform-wide (no other instances of this class). Fixed via migration 078: ENABLE ROW LEVEL SECURITY plus a single public-SELECT policy, no write policies at all (there is no user-facing pricing-edit flow; plan changes go through service_role only, matching rate_limit_attempts\' no-direct-grants convention). Verified live against prod: anon SELECT still returns real pricing, and a live anon PATCH attempt on the starter plan\'s price now affects 0 rows (204, price confirmed unchanged) where it would previously have succeeded.'],
  ['SEC-026', 'Data Access (RLS)', 'MEDIUM', 'platform_search_index (granted to anon) leaks content past its own intended RLS', 'deployment/migrations/037_platform_search_index_v2.sql:45-61 (adds discussions.body, builder_projects to an anon-granted view; 024\'s own comment warned against this)', 'Anonymous visitors can read discussion bodies and builder projects that their own table RLS says should require authentication.', 'Fixed', '2026-08-24', '2026-08-26', 'The view ran with its owner\'s (postgres) privileges by default, bypassing every underlying table\'s RLS -- 024\'s own comment predicted exactly this risk for discussions/projects, but 037 added them without revisiting it. Also found a second, narrower leak in the same view along the way: posts\' RLS restricts published rows by view_audience (public/follower/verified_expert), but the view\'s WHERE only checked status=\'published\', so anon could read verified_expert-only posts through search too -- confirmed live against real prod data (46 published posts, only 11 view_audience=\'public\'; before the fix anon could read all 46 through the index). Fixed via ALTER VIEW ... SET (security_invoker = true) (079, same technique as SEC-013\'s collaborators fix) -- makes the view respect the querying role\'s own RLS instead of the owner\'s bypass. jobs (open/filled) and gigs (active) both already have genuinely public SELECT policies, so anonymous visitors\' legitimate search results are unaffected. Verified via direct SQL (anon now sees only the 11 public posts, 0 discussions/projects; an authenticated caller sees projects too) and ecosystem-search-coverage.spec.ts passing clean (confirms authenticated search still surfaces a real Salt & Pepper discussion).'],
  ['SEC-027', 'Data Access (RLS)', 'MEDIUM', 'activity_feed bypasses the view_audience=\'verified_expert\' restriction on posts', 'deployment/migrations/053_activity_feed.sql:110-122 (selects published posts unfiltered)', 'A post intended to be Verified-Expert-only still surfaces to any follower via the activity feed.', 'Fixed', '2026-08-24', '2026-08-26', 'Same root cause and same fix as SEC-026: this view\'s own migration comment (053) claimed "security comes entirely from each UNIONed table\'s own existing RLS still applying per-invoker" -- untrue as deployed, since security_invoker was never actually set, so the view ran with owner-bypass privileges the whole time despite the comment\'s assumption. Fixed via ALTER VIEW ... SET (security_invoker = true) (080). Verified via a rolled-back transaction with fabricated test data: a non-verified-expert follower could see a verified_expert-only post from a followed author before the fix, and correctly got 0 rows after. Confirmed no regression via the pre-existing activity-feed.spec.ts (stackedge) passing clean (a follower still correctly sees a followed Builder\'s public project update but not their private one).'],
  ['SEC-028', 'Dependencies', 'MEDIUM', 'nodemailer has a high-severity "email to unintended domain" CVE', 'apps/greyin-b2b/src/lib/email.ts; package.json nodemailer ^6.10.1', 'Confirm exact usage (password reset vs. notification-only) before assessing urgency; fixed by a dependency bump.', 'Fixed', '2026-08-24', '2026-08-26', 'Confirmed via npm audit: nodemailer <=9.0.0 carries 8 advisories in this codebase\'s range, the two most serious both HIGH -- GHSA-p6gq-j5cr-w38f (message-level raw option bypasses disableFileAccess/disableUrlAccess, enabling SSRF/arbitrary file read in the delivered message) and GHSA-rcmh-qjqh-p98v (addressparser ReDoS, plausibly reachable here since a recipient\'s display name is sometimes user-influenced text, e.g. a profile\'s full_name). Confirmed via reading the 3 affected apps\' lib/email.ts (freeagent-marketplace, greyin-b2b, greymatters-blog -- the only 3 using nodemailer) that actual usage is the plain createTransport({host,port,secure,auth}) + sendMail({from,to,subject,html}) shape, never raw/jsonTransport/custom transport-name, so none of the option-specific CVEs were directly exploitable through this codebase\'s own code, but the addressparser ReDoS parses every from/to string regardless. This is confirmed general-notification usage, not the GoTrue-native password-reset flow (that goes through Supabase Auth\'s own Go-based mailer, unrelated to this npm package) -- password-reset urgency assessment doesn\'t apply here, general notification-email availability does. Bumped 6.x -> 9.0.5 (semver-major) in all 3 apps; confirmed all 3 Dockerfiles already use node:20-alpine, satisfying 9.x\'s Node>=20 engine requirement in production (the EBADENGINE warning during local install only reflected the dev shell\'s Node 18). tsc clean, npm audit confirms nodemailer entries gone in all 3 apps, deployed and smoke-checked. Verified with a real end-to-end send (not just install/typecheck): ran the exact createTransport/sendMail code shape from lib/email.ts directly against the real production SMTP relay under Node 20 -- message accepted and delivered.'],
  ['SEC-029', 'Data Access (RLS)', 'LOW', 'Newsletter signup allows anonymous insert with WITH CHECK (true)', 'deployment/migrations/008_newsletter.sql:23-25', 'Spam/enumeration surface on the newsletter table.', 'Fixed', '2026-08-24', '2026-08-26', 'The app\'s own route already treated a 23505 (duplicate email) response as success, but that was UI-layer only -- a direct call to /rest/v1/newsletter_subscribers (bypassing the app entirely) still got a genuinely different response (409 vs 201) for an already-subscribed email, a real enumeration oracle RLS can\'t suppress since it\'s a UNIQUE constraint violation, not an authorization decision. Fixed via a new subscribe_to_newsletter(email) SECURITY DEFINER RPC (081) that does INSERT ... ON CONFLICT DO NOTHING and always returns the same thing either way; the direct table INSERT grant is revoked so the enumerable raw endpoint isn\'t reachable at all. App route updated to call the RPC instead. Verified via direct SQL: a direct table insert as anon now fails with permission denied, and the RPC succeeds identically for both a fresh and a duplicate email (confirmed exactly one row ever inserted).'],
  ['SEC-030', 'Data Access (RLS)', 'LOW', 'get_unread_message_count() is SECURITY DEFINER with public execute and no authz', 'deployment/migrations/005_direct_messaging.sql:83-94', 'Count-only information leak; low severity but PUBLIC EXECUTE on a function with no auth.uid() check.', 'Fixed', '2026-08-24', '2026-08-26', 'Confirmed via pg_proc.proacl that PUBLIC (including anon) genuinely had EXECUTE. Two real leaks, not just the one named in the finding: nothing stopped p_user_id from being someone else\'s id (read another user\'s unread count), and even pinning p_user_id to the caller, SECURITY DEFINER bypasses order_messages\' own RLS, so a caller who wasn\'t a real participant in p_order_id still got a real message count for that order (every message there, since none were "from" them) -- a leak of private order conversations they have no relation to. Fixed (082) by requiring auth.uid() = p_user_id and requiring the caller actually be the buyer or seller on that order (returns 0 for anyone else, matching the function\'s original "just a count" contract rather than erroring), plus REVOKE/GRANT closing the PUBLIC/anon execute grant. Confirmed via a full codebase grep that this function is currently dead code (no app caller anywhere), so the tightened authorization carries zero regression risk. Verified via direct SQL: anon is now fully blocked (permission denied), and both the wrong-user-id and non-participant cases safely return 0 rather than erroring or leaking.'],
  ['SEC-031', 'Privacy', 'LOW', 'A candidate can list any user as a professional reference without that person\'s consent', 'deployment/migrations/065_reference_checks.sql:89-91', 'By design per explicit user direction (2026-08-24 build) — noted here as a privacy consideration to track, not a bug to silently fix.', 'Acknowledged — by design, not being changed', '2026-08-24', '2026-08-26', 'Reviewed again during this audit\'s LOW-severity pass and confirmed unchanged: this is an intentional product decision made explicitly by the user during the original 2026-08-24 build, not a defect. No code or DB change made -- listed here only so the traceability doc shows every finding was actually looked at, not silently skipped.'],
  ['SEC-032', 'Data Access (RLS)', 'LOW', 'StackWorks skill-rating interaction gate is satisfiable by a single DM', 'deployment/migrations/054_skill_endorsements_and_ratings.sql:182-187', 'Enables drive-by 1-star ratings with minimal real interaction.', 'Fixed', '2026-08-24', '2026-08-26', 'The "informal chat" branch of the initial skill-rating gate only required a single direct_messages row to exist in a shared conversation -- satisfiable by the rater sending one throwaway DM the target never had to reply to, then immediately posting a public 1-star rating. Fixed (083) by requiring messages from BOTH participants, not just any single message\'s existence -- a real two-way exchange, still cheap/lightweight (no minimum count or length), just no longer a pure drive-by. Verified via direct SQL in a rolled-back transaction with fabricated test data: a one-sided DM is now rejected by RLS, and a genuine two-way exchange still succeeds. Found and fixed a real regression along the way: e2e/utils/admin.ts\'s createTestConversationWithMessage helper only ever seeded one side of the conversation (matching the old, vulnerable behavior) -- the pre-existing skill-ratings.spec.ts (stackedge) failed against the tightened policy until the helper was updated to seed both sides; both stackedge and freeagent skill-ratings.spec.ts pass clean after that fix.'],
  ['SEC-033', 'Payments & Escrow', 'LOW', 'payout_requests accepts a client-supplied amount at insert time', 'deployment/migrations/014_payouts.sql:37-39', 'The real balance check happens in application code, not the database — defense-in-depth gap rather than an active hole today.', 'Fixed', '2026-08-24', '2026-08-26', 'The app\'s own route (api/payouts/request/route.ts) already recomputes the real available balance server-side and rejects an over-limit request, but nothing at the DB level enforced this -- a direct PostgREST insert (bypassing the route) could put in a payout_requests row for any amount. Real-money exposure was already limited (an admin manually reviews and processes every request out-of-band, no live payout-rail integration exists), matching the finding\'s own "not an active hole today" framing, but a fraudulent row was still a real gap an inattentive approval could act on. Fixed (084) with a BEFORE INSERT trigger that recomputes the exact same formula the app route already uses (2% platform fee off completed orders as seller, minus already-requested non-rejected amounts) and rejects anything over the real available balance, regardless of which path the row came through. Verified via direct SQL: a wildly over-limit request is rejected with the real error, and a legitimate within-balance request still succeeds. Confirmed no regression via earnings-and-payouts.spec.ts passing clean.'],
  ['SEC-034', 'Hardening', 'LOW', '~36 of 69 SECURITY DEFINER functions lack an explicit SET search_path', 'Various migrations across the tree', 'Best-practice hardening gap; low real exploitability on a Supabase-managed instance.', 'Fixed', '2026-08-24', '2026-08-26', 'Re-checked via pg_proc.proconfig and found only 15 of the current 59 SECURITY DEFINER functions still missing an explicit search_path (down from the original ~36 -- most had already picked one up incidentally from functions written or touched earlier in this same audit). Closed the remaining 15 with plain ALTER FUNCTION ... SET search_path = public statements (085) -- pure metadata changes, no function bodies touched, zero behavior change for any legitimate caller. Included the 3 real Razorpay payment functions (capture_razorpay_payment, create_razorpay_order, process_razorpay_refund), so re-ran the core payment e2e specs (order-lifecycle.spec.ts, escrow-workflow.spec.ts) afterward as an extra precaution given the payment-path overlap -- both passing clean. Verified via direct SQL that 0 SECURITY DEFINER functions remain without search_path set.'],
  ['SEC-035', 'Payments & Escrow', 'LOW', 'No idempotency key or row lock on Razorpay refund calls', 'apps/freeagent-marketplace/src/app/api/orders/cancel/route.ts; api/admin/orders/resolve-dispute/route.ts', 'Two concurrent cancel requests on the same paid order could issue two refunds — a narrow race window.', 'Fixed', '2026-08-24', '2026-08-26', 'Confirmed the gap was real: refundPayment()\'s third argument only goes into Razorpay\'s notes field (plain metadata), not the real X-Razorpay-Idempotency-Key mechanism, so Razorpay itself doesn\'t dedupe concurrent refund calls either. Fixed with a claim-then-act pattern (086, same shape as this codebase\'s existing atomic-claim RPCs like book_mentor_slot): two new SECURITY DEFINER functions, claim_order_cancellation_refund and claim_order_dispute_refund, each do a real SELECT ... FOR UPDATE row lock plus the same buyer/admin+status authorization checks the app routes already had, and atomically mark refund_status=\'pending\' as a claim before returning success -- a second concurrent/replayed call blocks on the lock, then sees the claim already taken and is refused, so it never reaches Razorpay. refund_status was already a real column (014/020), previously write-only and unused for any check, so repurposing its \'pending\' value as the claim marker didn\'t collide with anything. Both app routes updated to call the claim RPC before invoking Razorpay, and to reset refund_status back to NULL on a Razorpay failure so a genuine retry stays possible. Verified via direct SQL (first claim succeeds, an immediate second claim attempt on the same order is refused) and escrow-workflow.spec.ts passing clean end to end (all 3 tests, including the real cancel-and-refund and admin-dispute-resolution flows that now go through the new claim RPCs).'],
  ['SEC-036', 'Dependencies', 'LOW', 'postcss / cookie / @supabase-ssr low-severity npm advisories', 'All 6 apps, transitive deps', 'Fixed incidentally by the Next.js version bump (SEC-014).', 'Fixed', '2026-08-24', '2026-08-26', 'postcss: fixed via an npm `overrides` field forcing Next.js\'s own nested/vendored copy up to 8.5.26 (required a full lockfile regeneration to actually take effect), verified clean in all 6 apps. @supabase/ssr: two attempts the same day. The first was a staged 1-app-then-5-more rollout (matching the SEC-016 precedent) -- rewrote get/set/remove to getAll/setAll (0.1.0 -> 0.12.5) in greyin-b2b alone, deployed, and it broke cross-app SSO live: the two library versions write session cookies in incompatible formats, so every app still on 0.1.0 failed to recognize a session started by the rewritten app (8 of 11 e2e tests failed, all cross-app, none same-app). Reverted immediately once confirmed, redeployed, reconfirmed 11/11 passing. Once the user confirmed no real end users are on the platform yet -- removing the live-session-compatibility constraint that made staging necessary -- reattempted as a true simultaneous all-6-apps cutover: rewrote all 6 apps\' middleware.ts + lib/supabase/server.ts via a verified script (each file\'s exact-match cookie-handling block confirmed found exactly once before substitution, cookieOptions.name and SEC-016\'s secure/sameSite/domain overrides preserved throughout, client.ts left unchanged), bumped all 6 to 0.12.5, built and deployed all 6 back-to-back with no staged pauses. Verified clean: npm audit shows both @supabase/ssr and cookie CVEs gone in all 6 apps, tsc clean, all 6 services converged with zero log errors, and the full auth e2e suite (14 tests -- signup, login, SSO across all 6 apps, logout, session-refresh, password-reset, security-regressions) passing clean end to end post-cutover. The failed staged attempt is preserved here rather than erased from the record: it is real, useful evidence that this specific library upgrade requires an atomic cutover, not incremental rollout, and that call was only safe to make because there were no live sessions to protect.'],
  ['SEC-037', 'Payments & Escrow', 'LOW', 'B2B subscription activation has no ownership check beyond the signature-bound ID', 'apps/greyin-b2b/src/app/api/subscriptions/checkout/verify/route.ts:52', 'Activates by razorpay_subscription_id with no separate ownership check; impact limited since that ID is itself signature-bound to the real payment.', 'Fixed', '2026-08-24', '2026-08-26', 'Added an explicit ownership check (a companies!inner(user_id) join confirming the authenticated caller owns the company that row belongs to) before activating a subscription, on top of the existing, unchanged Razorpay HMAC signature check -- closes the narrow gap where whoever held a valid signature triple for a subscription (by construction, whoever completed that specific Razorpay checkout) could activate it regardless of which authenticated session submitted the verify call. Also fixed a related completeness gap noticed while touching this code: activated_by/activated_at were always NULL, never actually set on activation -- now populated from the real caller. Verified via tsc --noEmit clean, deployed, and covered by the broader e2e regression pass (sso/logout-flow/security-regressions/escrow-workflow/order-lifecycle, 15/15 passing) -- no dedicated spec exists for this specific route, judged proportionate for a LOW-severity defense-in-depth addition where the real authorization boundary (the signature check) is unchanged.'],
  ['SEC-038', 'Dependencies', 'HIGH', 'Large batch of newly-disclosed Next.js CVEs (SSRF in Server Actions/rewrites, DoS, middleware/i18n bypass, cache poisoning, XSS) spanning 9.x-15.5.x', 'apps/*/package.json (all 6 apps), next 14.2.35', 'Real fix (next@16.3.3) is a 2-major-version jump touching App Router/Server Components/routing/middleware across the whole platform -- out of scope for a same-session fix given the regression risk and the precedent already set this session by the far smaller 14.2.4->14.2.35 patch bump breaking a real route. Deliberately not attempted; flagged as a dedicated follow-up effort needing its own planning and full regression pass, not bundled into this audit.', 'Open — flagged as out-of-scope, needs dedicated follow-up effort (2-major-version Next.js bump)', '2026-08-26', '', ''],
  ['SEC-039', 'Privacy', 'MEDIUM', 'peer_project_ratings\' first-shipped SELECT policy was USING(true) -- individual rater->ratee rows publicly queryable by anyone via PostgREST, following company_reviews\' (058) "anonymity is an app-layer convention, not access control" precedent', 'deployment/migrations/089_peer_projects.sql (original policy, superseded)', 'Caught before rollout, not in production: the user\'s own explicit requirement ("who gave what is not visible... anonymous aggregation for the end user") is materially stronger than company_reviews\' precedent -- any authenticated user could otherwise query ?rater_id=eq.X directly and see exactly who rated whom what, bypassing the app UI\'s anonymity entirely.', 'Fixed', '2026-09-02', '2026-09-02', 'Tightened (090) to USING(auth.uid()=rater_id OR employer/admin) before this feature was ever deployed to any real user -- a regular member now sees only ratings they personally gave; nobody else\'s, at the RLS layer itself, not by app convention. Employers/admins get purpose-built aggregate views instead (peer_rater_reliability, peer_project_reciprocity_flags), each independently gated via their own EXISTS(...role IN (employer,admin)) clause baked into the view\'s WHERE, since the tightened base-table policy alone no longer exposes rows broadly enough for an aggregate view to rely on. Verified via direct RLS simulation as rater/non-rater/employer/admin (all four cases: own-rating visible, others\'-rating hidden, employer aggregate visible, non-employer aggregate empty) and end-to-end via peer-projects.spec.ts.'],
  ['SEC-041', 'Payments & Escrow', 'MEDIUM', 'A subscription tier\'s cached razorpay_plan_id (096) was never invalidated when an admin changed that tier\'s price_inr, so every subsequent checkout kept billing the old price indefinitely, silently, with no error surfaced anywhere.', 'apps/deepedge/src/app/api/admin/subscription-tiers/update/route.ts; apps/flexpro/src/app/api/admin/subscription-tiers/update/route.ts; the shared subscriptions/checkout/create routes that create-and-cache the Razorpay plan on first use', 'Found while auditing the pitch-deck cost model for whether CAC/advertising spend was reflected in it, which prompted a side question about whether admin-set tier pricing actually took effect end to end. Razorpay plans are immutable (no update-price API), so the lazy-create-and-cache-forever pattern is correct on its own -- the bug was that price_inr changing in the DB was never treated as a reason to also clear the cache. Not caught by any existing test, since nothing previously drove the admin price-change form against a tier that already had a cached plan.', 'Fixed', '2026-09-08', '2026-09-08', 'Both admin update routes now read the tier\'s current price_inr and razorpay_plan_id before writing, and null out razorpay_plan_id in the same update only when price_inr actually changed -- an admin editing just a credit allowance no longer forces a needless new Razorpay plan on the next checkout, and existing subscribers already on the old cached plan are correctly unaffected (they keep their current price until they resubscribe). Added subscription-tier-price-update.spec.ts for both apps, driving the real admin form end to end against a tier pre-seeded with a fake cached plan id: proves an allowance-only save leaves it untouched and an actual price change clears it. One of the two apps\' add/remove-tier capability was also checked as part of this pass and confirmed still absent (admin can only edit existing tier rows, matching the already-known limitation) -- not a new gap, not in scope of this fix.'],
  ['SEC-040', 'Privacy', 'HIGH', 'collaborators view lost security_invoker=true when 089_peer_projects.sql recreated it (CREATE OR REPLACE VIEW does not preserve reloptions from the version it replaces), reverting to Postgres\'s default security_definer-like behavior under the view owner (postgres) -- combined with anon holding PostgREST\'s standard SELECT grant on every view, this meant the underlying tables\' RLS (project_applications/project_asks/gig_orders/peer_project_members, each scoped to the specific applicant/owner/buyer/seller/peer-member) was not enforced at all when queried through this view.', 'deployment/migrations/067_security_critical_fixes.sql (original security_invoker=true setting); 089_peer_projects.sql (the CREATE OR REPLACE VIEW that silently dropped it). Flagged, not fixed, during the 2026-08-31 freeagent->flexpro rename (found incidentally while checking view reloptions before an unrelated migration) -- sat open for days.', 'Confirmed live and exploitable before fixing, not theoretical: a plain unauthenticated curl (public anon key only, zero login) against /rest/v1/collaborators?select=*&limit=5 returned real cross-user, cross-pillar collaboration pairs (user_id/collaborator_id/pillar/occurred_at) platform-wide -- anyone could enumerate every "who has worked with whom" pairing across StackWorks/FlexPro/peer-projects with no account at all.', 'Fixed', '2026-08-31 (flagged)', '2026-09-05', 'Re-applied security_invoker=true via 115_fix_collaborators_security_invoker.sql. Before touching anything, checked all 5 real call sites in the codebase (greyin-hub/dashboard, stackworks/people, saltnpepper-community/members, deepedge/candidates/[id], flexpro/sellers/[id]) -- every one filters .eq(\'user_id\', <the current authenticated viewer\'s own id>), so in every legitimate row the viewer IS one of the two collaborating parties, exactly what each underlying table\'s own RLS already permits for its applicant/owner/buyer/seller/peer-member; the fix could not break any real usage. Verified via the identical unauthenticated curl immediately after (now returns []), and via the full set of specs that exercise this view\'s real functionality end to end (skill-endorsements, written-recommendations, peer-projects, worked-together on StackWorks, and worked-together-surfacing.spec.ts specifically -- which asserts both that real collaborators see each other AND that "a stranger sees neither") -- all 5 passed clean. Added a permanent regression guard to security-regressions.spec.ts (a plain unauthenticated request against /rest/v1/collaborators must always return zero rows) so this can never silently regress again the way it did for over a week the first time. CORRECTED 2026-09-07: the guard\'s original zero-rows assertion went stale, not the fix -- peer_project_members later gained its own deliberate "confirmed members are public" RLS policy (087-092, the peer-projects feature), which security_invoker correctly, faithfully propagates through this view to anon too. Confirmed live that zero stackworks/flexpro rows still ever reach anon (the actual SEC-040 protection remains fully intact) and narrowed the guard\'s assertion to that real invariant specifically, rather than a total-row-count a later, unrelated, intentional feature was always going to break.'],
]

const wb = XLSX.utils.book_new()

function addSheet(name, rows, colWidths) {
  const ws = XLSX.utils.aoa_to_sheet(rows)
  ws['!cols'] = colWidths.map((w) => ({ wch: w }))
  ws['!freeze'] = { xSplit: 0, ySplit: 1 }
  XLSX.utils.book_append_sheet(wb, ws, name)
}

addSheet('Functional Requirements', functional, [16, 26, 10, 70, 16, 12])
addSheet('Non-Functional Requirements', nonFunctional, [20, 12, 60, 60, 12])
addSheet('Traceability Matrix', traceability, [10, 40, 12, 16, 30, 45, 12, 14])
addSheet('Audit Roadmap', roadmap, [4, 60, 18, 28, 10, 14, 60])
addSheet('Pending Partial Deferred', pending, [36, 26, 70, 40, 14])
addSheet('Security Findings', securityFindingsRaw, [9, 18, 10, 55, 50, 55, 10, 12, 12, 60])

const outPath = process.argv[2]
XLSX.writeFile(wb, outPath)
console.log('Wrote', outPath)
console.log('Functional requirements:', functional.length - 1)
console.log('Non-functional requirements:', nonFunctional.length - 1)
console.log('Security findings:', securityFindingsRaw.length - 1)
console.log('Traceability rows:', traceability.length - 1)
console.log('Audit roadmap items:', roadmap.length - 1)
console.log('Pending/partial/deferred:', pending.length - 1)
